mapper.select:


    o.is_del = '0'

        AND o.order_no like concat('%', #{orderNo}, '%')


        AND o.customer_id = #{customerId}


        AND o.customer_name like concat('%', #{customerName}, '%')


        AND o.bill_status = #{billStatus}


        AND o.business_type = #{businessType}


        AND o.sales_type = #{salesType}


        AND o.settlement_method = #{settlementMethod}


        AND o.sales_person = #{salesPerson}


        AND o.contract_no like concat('%', #{contractNo}, '%')


        AND o.bill_date >= #{billDateBegin}


        AND o.bill_date <= #{billDateEnd}


order by o.order_id desc
